-- ---------------------------------------------------------------------------
-- NEOP selection exam question bank (70 items: 26 clinical, 33 operations, 11 fit).
--
-- GENERATED by scripts/gen-neop-exam.mjs from scripts/neop-exam-bank.mjs.
-- Do not hand-edit: edit the bank and run `npm run check:neop`, which
-- regenerates nothing but tells you this file has drifted.
--
-- Requires the 2026-08-18-neop-selection-exam.sql migration (or a schema.sql
-- new enough to contain the program/section/code columns).
--
-- SAFE TO RE-RUN, and safe to re-run against a live exam. It upserts on
-- `code` and never deletes: an id already recorded in
-- exam_attempts.question_ids keeps its row and its meaning. Items removed from
-- the bank are retired (active = false) rather than dropped, so a historical
-- attempt still resolves to the question it actually asked.
--
-- The AEMT bank is untouched — every statement here is fenced to
-- program = 'neop'.
--
-- The preference items carry answer = null on purpose. That is what makes them
-- unscored: the database generates `scored` from it and exam_submit skips
-- them. Giving one of them a key would score a candidate on what they want.
-- ---------------------------------------------------------------------------

insert into public.exam_questions (program, section, code, domain, stem, options, answer, active)
select 'neop', v.section, v.code, v.domain, v.stem, v.options, v.answer, true
from (values
('clinical', 'clin-deteriorates', 'Transport care', 'Twenty minutes into a transport your patient becomes unresponsive. Your first action is to:', array['call the receiving facility for instructions','check the airway and breathing','note the time in your report','ask your partner to drive faster'], 1),
('clinical', 'clin-trend', 'Assessment', 'Over three sets of vitals your patient''s systolic blood pressure has fallen from 130 to 118 to 104, and the pulse has risen each time. The right reading of this is:', array['nothing to act on until a reading is actually abnormal','a trend that matters now, and is worth acting on and reporting early','a normal response to the movement of the vehicle','evidence that the cuff size is wrong'], 1),
('clinical', 'clin-unstable-reassess', 'Assessment', 'An unstable patient should be reassessed at least every:', array['5 minutes','15 minutes','30 minutes','once on arrival'], 0),
('clinical', 'clin-avpu', 'Assessment', 'AVPU is used to assess:', array['pupil size and reaction','level of consciousness','skin color and temperature','the severity of pain'], 1),
('clinical', 'clin-early-shock', 'Assessment', 'Early (compensated) shock in an adult typically presents as:', array['a low blood pressure with a slow pulse','a fast pulse and pale, cool skin with a blood pressure still in range','warm, flushed skin with a slow pulse','no change at all until the patient collapses'], 1),
('clinical', 'clin-position-resp', 'Airway', 'A conscious patient in respiratory distress, with no trauma, is best transported:', array['flat on their back','head-down','sitting upright','face-down'], 2),
('clinical', 'clin-hypoxia', 'Airway', 'Hypoxia is best defined as:', array['too much carbon dioxide in the blood','inadequate oxygen at the tissue level','a raised respiratory rate','a low circulating blood volume'], 1),
('clinical', 'clin-nrb-flow', 'Airway', 'A non-rebreather mask should be run at a flow rate of:', array['2 L/min','4 to 6 L/min','12 to 15 L/min','25 L/min'], 2),
('clinical', 'clin-pulseox-co', 'Airway', 'A pulse oximeter can read falsely high in a patient who has:', array['a fever','been exposed to carbon monoxide','received supplemental oxygen','a fast heart rate'], 1),
('clinical', 'clin-copd-oxygen', 'Airway', 'A patient with a long history of COPD is clearly hypoxic. You should:', array['withhold oxygen because of the COPD history','give oxygen and titrate it to their oxygen saturation','give oxygen only if they ask for it','wait until arrival and let the receiving facility decide'], 1),
('clinical', 'clin-suction', 'Airway', 'A patient on your cot vomits and is unable to clear it. Your first action is to:', array['raise the head of the cot and continue','clear the airway with suction and position the patient to protect it','give oxygen by non-rebreather','document the time and notify the receiving nurse'], 1),
('clinical', 'clin-glucose', 'Medical', 'A patient becomes confused and sweaty during a transport. The most rapidly correctable cause to check for is:', array['a stroke','a low blood glucose','a brain tumour','a migraine'], 1),
('clinical', 'clin-anaphylaxis', 'Medical', 'Hives, wheezing and a falling blood pressure shortly after a medication is given indicate:', array['an anxiety attack','anaphylaxis','a fainting episode','a normal reaction to a first dose'], 1),
('clinical', 'clin-stroke-lkw', 'Medical', 'For a stroke patient being transferred for treatment, the single time the receiving team most needs from you is:', array['when the transfer was requested','when the patient was last known well','when you arrived at the sending facility','when the vital signs were last taken'], 1),
('clinical', 'clin-lines-before-move', 'Moving patients', 'Before moving a patient from a hospital bed onto your cot, you should:', array['disconnect every line so nothing can catch','check that every line, tube and drain is free and long enough for the move','move first and sort the lines out once the patient is across','ask the patient to hold their own lines'], 1),
('clinical', 'clin-heavy-lift', 'Moving patients', 'A patient is heavier than the two of you can move safely. The right thing to do is:', array['move quickly with the two of you to limit the strain','get more hands and the right transfer equipment, even though it delays departure','ask the patient to take their own weight','drag the patient across on the bed sheet'], 1),
('clinical', 'clin-straps', 'Moving patients', 'A patient is being transported on the cot. The cot straps should be:', array['all fastened, including the shoulder straps, for the whole transport','fastened only across the waist so the patient can sit up','left loose for a short trip','fastened only if the patient is unresponsive'], 0),
('clinical', 'clin-confused-cot', 'Moving patients', 'You are moving a confused patient from a nursing facility. The most important safety measure is:', array['to keep the patient restrained at the wrists','to keep the rails up, the straps secured, and the patient never left unattended','to transport with a family member at the head of the cot','to sedate the patient before departure'], 1),
('clinical', 'clin-precautions', 'Infection control', 'A patient is on contact precautions at the sending facility. During and after the transport you should:', array['use the same precautions the facility uses, and disinfect the cot and equipment afterwards','treat the transport normally, since precautions apply only in the building','use a mask alone','ask the facility to send the patient without any precautions'], 0),
('clinical', 'clin-report-received', 'Handover', 'You are taking report from the sending nurse on an ICU patient. The most useful question you can add is:', array['how long the patient has been in the hospital','what has changed in the last hour, and what they are worried about','who the admitting physician was','whether the family has been notified'], 1),
('clinical', 'clin-handover-give', 'Handover', 'At the receiving facility, your verbal handover should always include:', array['only what has changed since the sending facility called','the patient, why they were transferred, and anything that changed during the transport','the route you took and the transport time','nothing — the written report covers it'], 1),
('clinical', 'clin-dnr-paperwork', 'Documentation', 'A patient with a valid do-not-resuscitate order is being transferred. Before leaving the sending facility you should make sure that:', array['the order is left at the sending facility','the original order travels with the patient','the order is void once the patient is in your care','the family carries the order separately'], 1),
('clinical', 'clin-chart-timing', 'Documentation', 'The best time to write your patient care report is:', array['at the end of the shift, when all the calls can be written together','as soon as practical after the transport, while the detail is accurate','only if something went wrong','before the transport, so it is ready'], 1),
('clinical', 'clin-chart-honest', 'Documentation', 'You realize on arrival that you missed a set of vital signs during a long transport. Your report should:', array['record what was actually done, including the gap','estimate the missing set from the readings either side','leave the section blank with no comment','record the set taken on arrival at the earlier time'], 0),
('clinical', 'clin-oxygen-supply', 'Equipment', 'Before setting off on a two-hour transport with a patient on oxygen, you should confirm that:', array['the cylinder is above half full','there is enough oxygen for the expected journey plus a reserve for delays','a spare mask is on board','the receiving facility has oxygen available'], 1),
('clinical', 'clin-equipment-check', 'Equipment', 'Equipment on the truck should be checked:', array['at the start of every shift, before it is needed','when a call comes in for a patient who needs it','weekly, by the crew assigned to the truck','only after it has been used'], 0),
('operations', 'ops-primary-work', 'Our operation', 'AMR Kansas City''s primary work is:', array['responding to 911 calls across the metro','moving patients between healthcare facilities','standby cover at public events','air ambulance and flight transport'], 1),
('operations', 'ops-normal-call', 'Our operation', 'Which of these is a normal call for this operation?', array['a multi-vehicle collision on the highway','an ICU patient moving to a hospital that can do something the sending one cannot','a cardiac arrest called in from a private residence','a stabbing outside a bar at closing time'], 1),
('operations', 'ops-geography', 'Our operation', 'The Kansas City operation works:', array['in Missouri only','in Kansas only','on both sides of the state line, in Missouri and Kansas','anywhere in the two states, dispatched from a single hospital'], 2),
('operations', 'ops-volume', 'Our operation', 'The operation runs roughly how many transports a month?', array['about a hundred','about a thousand','about ten thousand','it varies too much to say'], 1),
('operations', 'ops-already-a-patient', 'Our operation', 'When you arrive at the sending facility, the patient has usually already been:', array['assessed and diagnosed, and started on a plan by a physician you will not meet','discharged from the care of the sending facility','assessed by the crew who transported them in','left for you to work up from the beginning'], 0),
('operations', 'ops-scene-calls', 'Our operation', 'How often will you be dispatched to a scene — a wreck, a shooting, a house call?', array['roughly half the time','a few times a shift','this operation does not respond to scenes','only when the 911 service asks for help'], 2),
('operations', 'ops-lights-sirens', 'Our operation', 'Emergency lights and sirens on this operation are:', array['used on most transports','the exception — most transports are made at ordinary road speed','used whenever the patient is on a ventilator','not carried on the trucks'], 1),
('operations', 'ops-known-before', 'Our operation', 'Before you touch the truck, you will usually know:', array['nothing beyond an address','the diagnosis, what is infusing or attached, and where the patient is going','the patient name only','whichever details the family has given dispatch'], 1),
('operations', 'ops-the-risk', 'Our operation', 'The briefing describes the main risk of this job as:', array['not knowing what you will find when you arrive','being solely responsible for an already-sick, complicated patient in a moving truck, with no help arriving','the number of miles driven each shift','exposure to violence at the roadside'], 1),
('operations', 'ops-patient-types', 'Our operation', 'Which describes the patients this operation routinely moves?', array['mostly walking patients going to appointments','patients on ventilators, sedation and infusions, alongside stable patients going home','trauma patients straight from the roadside','newborns only'], 1),
('operations', 'ops-mcs-teams', 'Our operation', 'Patients on mechanical circulatory support — a balloon pump, Impella or ECMO:', array['are managed by our crew alone once the doors close','are familiar to our crews and travel with their own specialist teams','are never moved by ground ambulance','are the most common patient we transport'], 1),
('operations', 'ops-stable-majority', 'Our operation', 'Stable patients — the ones who need a safe ride and decent manners and nothing else — are:', array['a small share of the work','most of the work','handled by a separate wheelchair service','transported only on weekends'], 1),
('operations', 'ops-vent-expectation', 'Our operation', 'A Kansas City paramedic is expected to:', array['manage the transport ventilator, not simply watch it','leave ventilator settings to the sending respiratory therapist','transport vented patients only with a nurse on board','switch every vented patient to a bag-valve mask for the trip'], 0),
('operations', 'ops-injury-source', 'Our operation', 'According to the briefing, injuries in this job come most often from:', array['violent patients','lifting and moving patients','road collisions','needlesticks'], 1),
('operations', 'ops-report-skill', 'Our operation', 'Taking report from an ICU nurse well means:', array['writing down what you are given and leaving promptly','getting the report and asking the questions it did not answer','asking the nurse to repeat it so it can be recorded word for word','waiting for the physician to give it instead'], 1),
('operations', 'ops-chart-justifies', 'Our operation', 'An interfacility patient care report has to establish:', array['how long the transport took','why this patient needed an ambulance and this level of care','which crew members were on the truck','the route driven between the two facilities'], 1),
('operations', 'ops-qa-sampling', 'Our operation', 'Our charts are reviewed:', array['only when a complaint is made','about a fifth of them, every month, against a written rubric','once a year at appraisal','by the receiving facility rather than by us'], 1),
('operations', 'ops-paperwork-warning', 'Our operation', 'The briefing says that an applicant who dislikes paperwork:', array['will get used to it within a few months','is looking at the wrong operation, because here documentation is part of the clinical work','can have charts written by their partner','should apply as an EMT rather than a paramedic'], 1),
('operations', 'ops-waiting', 'Our operation', 'Waiting — at a bedside for a nurse, or at the receiving end for a bed assignment — is:', array['rare, and a sign something has gone wrong','a normal part of the shift','billed to the sending facility and therefore avoided','grounds for leaving without the patient'], 1),
('operations', 'ops-long-transports', 'Our operation', 'Transport distances on this operation:', array['are all short trips across the metro','range from twenty minutes across town to journeys of hours each way','are capped at one hour by policy','are always within a single county'], 1),
('operations', 'ops-quiet-shift', 'Our operation', 'You finish a shift having moved several patients well and having used none of your emergency skills. The briefing describes that as:', array['a slow day that should be reported to a supervisor','a normal day, and a genuinely useful one','a sign you were assigned the wrong truck','unusual on this operation'], 1),
('operations', 'ops-guest', 'Our operation', 'On most calls in this operation, in someone else’s ICU or nursing facility, you are:', array['in charge of the scene, as on a 911 call','a guest in their building','responsible for the unit until you leave','there only to collect paperwork'], 1),
('operations', 'ops-reputation', 'Our operation', 'How a crew behaves in a facility hallway matters because:', array['the facilities score every crew formally each quarter','you will see the same staff every week, and it is most of our reputation','the hallways are monitored by hospital security','it affects the billing for the transport'], 1),
('operations', 'ops-hallway-sjt', 'Our operation', 'An ICU nurse keeps you waiting forty minutes and is short with you when she finally gives report. The response that fits this operation is to:', array['match her tone so it does not happen again','stay courteous, get the report you need for the patient, and raise any real problem afterwards through your supervisor','say nothing at the time and leave the incident out of the record','call dispatch from the hallway to have the transport reassigned'], 1),
('operations', 'ops-career-direction', 'Our operation', 'The career path the briefing describes runs toward:', array['scene response and rescue work','critical care, field training, education and quality review','dispatch and communications','hospital employment'], 1),
('operations', 'ops-linn-cass', 'Our operation', 'The 911 work this company does in the region is:', array['run out of the Kansas City interfacility trucks','in Linn County, Kansas — a rural 911 operation with two round-the-clock trucks — and Cass County, Missouri, which runs a transport truck of its own','contracted out to another provider','available to Kansas City crews as overtime shifts'], 1),
('operations', 'ops-not-a-queue', 'Our operation', 'Taking a seat here in order to move across to a 911 operation later is:', array['the usual route people take, and it works','not how it works — those are separate operations with their own postings, and nobody moves across by waiting','possible after twelve months of service','decided by seniority each January'], 1),
('operations', 'ops-say-so', 'Our operation', 'If 911 response is the career an applicant actually wants, the briefing asks them to:', array['keep it to themselves until after the probation period','say so — it is a respectable answer, and we would rather hear it now','apply anyway and decide later','withdraw their application'], 1),
('operations', 'ops-ask-dont-guess', 'Our operation', 'On this operation, when you do not know something:', array['asking is the professional behavior and guessing is the dangerous one','you are expected to work it out yourself before asking','you should ask the facility staff rather than your own people','it is best raised after the transport, in the report'], 0),
('operations', 'ops-honest-chart', 'Our operation', 'The standard the briefing sets for your documentation is that it is:', array['complete enough to satisfy billing','honest, including the parts that do not flatter you','brief, so the crew stays available','written to match what the sending facility recorded'], 1),
('operations', 'ops-neop-length', 'Our operation', 'The New Employee Orientation Program classroom runs:', array['two days, on your first weekend','roughly a week and a half, and is held every other month','six weeks, full time','entirely online, at your own pace'], 1),
('operations', 'ops-medic-block', 'Our operation', 'Paramedics coming into Kansas City add which block to the standard orientation?', array['rescue and extrication','ventilator management, and vasopressor and sedative infusions','dispatch and radio operations','community paramedicine'], 1),
('operations', 'ops-release', 'Our operation', 'You are released to work as a crew member:', array['on a fixed date at the end of orientation','after roughly twenty to thirty patient contacts, when your field training officer signs you off','once you have completed ninety days','as soon as the classroom week finishes'], 1),
('fit', 'fit-future', 'What you want', 'Three years from now, the job you would most want to be doing is:', array['interfacility and critical-care transport — the work described above','911 scene response, at a fire department or a municipal EMS service','a hospital, clinic or flight role, with EMS as the step toward it','I do not know yet — I want to see more of the work first'], null),
('fit', 'fit-draw', 'What you want', 'What drew you to EMS in the first place?', array['emergencies — being the person who goes toward them','looking after sick people, wherever they happen to be','a stable job with a schedule and somewhere to go in it','it is a step toward another healthcare career'], null),
('fit', 'fit-shift', 'What you want', 'Which shift would you rather work?', array['eleven quiet hours and one cardiac arrest','five stable transfers with drips and a ventilator, and nothing that goes wrong','whichever one pays the same — I have no preference','back-to-back calls all shift, whatever they turn out to be'], null),
('fit', 'fit-tradeoff', 'What you want', 'If you had to give one of these up, which would you give up more easily?', array['running emergencies','working with critically ill patients','neither — I want both, and I know I cannot have both here','either one, if the schedule and the pay are right'], null),
('fit', 'fit-911-offer', 'What you want', 'Six months in, a 911 position opens at another service at the same pay. You:', array['take it — 911 is the work I want','stay — this is the work I want to be doing','look at it, but expect to stay if things are going well here','decide on the schedule and the money'], null),
('fit', 'fit-honest', 'What you want', 'Being honest: how much of your interest in this job is that it is the opening available right now?', array['none — this is the job I want','some — but the work itself interests me','a lot — I need a job, and this is the one that is open','hard to say'], null),
('fit', 'fit-least', 'What you want', 'Which part of this job do you expect to like least?', array['the waiting — at bedsides, and for bed assignments','the documentation','not using emergency skills often','the long transports'], null),
('fit', 'fit-paperwork', 'What you want', 'On documentation, the statement closest to you is:', array['it is the part of the job I would have to make myself do','it is part of patient care, and I would rather be good at it','I am quick at it and I keep it short','I have not done much of it yet'], null),
('fit', 'fit-alone', 'What you want', 'Being alone in the back with a complicated but stable patient for forty-five minutes is:', array['the part I would find hardest','the part I would find most rewarding','neither — it does not concern me either way','something I would want more training on before I was comfortable with it'], null),
('fit', 'fit-experience', 'What you want', 'Which best describes your EMS experience so far?', array['none yet — I am new to it','911 or scene work only','interfacility or transport work','both scene and transport work'], null),
('fit', 'fit-stay', 'What you want', 'If you took this job and it went well, how long would you expect to be here?', array['under a year','a year or two','three years or more','as long as it suits both of us'], null)
) as v(section, code, domain, stem, options, answer)
on conflict (code) where code is not null do update
  set section = excluded.section,
      domain  = excluded.domain,
      stem    = excluded.stem,
      options = excluded.options,
      answer  = excluded.answer,
      active  = true;

-- Retire anything no longer in the bank. Never deleted — see the header.
update public.exam_questions
   set active = false
 where program = 'neop'
   and active
   and code not in ('clin-deteriorates', 'clin-trend', 'clin-unstable-reassess', 'clin-avpu', 'clin-early-shock', 'clin-position-resp', 'clin-hypoxia', 'clin-nrb-flow', 'clin-pulseox-co', 'clin-copd-oxygen', 'clin-suction', 'clin-glucose', 'clin-anaphylaxis', 'clin-stroke-lkw', 'clin-lines-before-move', 'clin-heavy-lift', 'clin-straps', 'clin-confused-cot', 'clin-precautions', 'clin-report-received', 'clin-handover-give', 'clin-dnr-paperwork', 'clin-chart-timing', 'clin-chart-honest', 'clin-oxygen-supply', 'clin-equipment-check', 'ops-primary-work', 'ops-normal-call', 'ops-geography', 'ops-volume', 'ops-already-a-patient', 'ops-scene-calls', 'ops-lights-sirens', 'ops-known-before', 'ops-the-risk', 'ops-patient-types', 'ops-mcs-teams', 'ops-stable-majority', 'ops-vent-expectation', 'ops-injury-source', 'ops-report-skill', 'ops-chart-justifies', 'ops-qa-sampling', 'ops-paperwork-warning', 'ops-waiting', 'ops-long-transports', 'ops-quiet-shift', 'ops-guest', 'ops-reputation', 'ops-hallway-sjt', 'ops-career-direction', 'ops-linn-cass', 'ops-not-a-queue', 'ops-say-so', 'ops-ask-dont-guess', 'ops-honest-chart', 'ops-neop-length', 'ops-medic-block', 'ops-release', 'fit-future', 'fit-draw', 'fit-shift', 'fit-tradeoff', 'fit-911-offer', 'fit-honest', 'fit-least', 'fit-paperwork', 'fit-alone', 'fit-experience', 'fit-stay');

-- Confirm the draw can be filled: 12 clinical, 16 operations, and at least one
-- preference item are needed before a candidate can start.
select section, count(*) filter (where active) as active_items, count(*) as total_items
  from public.exam_questions
 where program = 'neop'
 group by section
 order by section;
